<?php declare(strict_types=1); namespace Annam; $title='Checkout & courier delivery'; ?>
<section class="o-card"><h2>Two delivery rules</h2><p>Breakfast, lunch and dinner use <a href="/manage/zones/">meal delivery areas</a>, including each area's fee and minimum. Shop items use the approved courier pincodes below. Customers outside coverage cannot order. Meals and shop items require separate orders.</p></section><form method="post" class="o-form"><?= csrf() ?><section class="o-card"><h2>Shop courier coverage</h2><p>Choose where Annam’s packed products can be delivered.</p><label class="php-switch-row"><input class="php-toggle" role="switch" type="checkbox" name="courier_enabled" value="1" <?= ($settings['courier_enabled']??false)?'checked':'' ?>><span><strong>Enable courier delivery for shop orders</strong><small>Accept orders only for approved pincodes below.</small></span><b class="php-switch-state" aria-hidden="true"></b></label><div class="o-actions"><h3>Approved Tamil Nadu courier pincodes</h3><button type="button" class="o-btn" id="add-pin">+ Add row</button></div><p>Enter one pincode per row, or paste a single column from Excel.</p><div class="o-table-wrap php-pin-table"><table class="o-table"><thead><tr><th>#</th><th>Delivery pincode</th><th>Action</th></tr></thead><tbody id="pin-rows"><?php foreach(($settings['courier_pincodes']??[])?:[''] as $index=>$pin): ?><tr><td><?= $index+1 ?></td><td><input name="pincodes[]" value="<?= e($pin) ?>" inputmode="numeric" maxlength="6" pattern="[1-9][0-9]{5}" aria-label="Delivery pincode"></td><td><button type="button" class="o-btn" data-remove-pin>Remove</button></td></tr><?php endforeach; ?></tbody></table></div><p id="pin-count"></p><p>Unlisted pincodes are blocked. Changes apply after saving.</p><div class="o-grid-form"><?php foreach(['courier_fee'=>'Flat courier charge (₹)','courier_minimum'=>'Minimum shop items subtotal (₹)'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($key) ?>" value="<?= e($settings[$key]??'0') ?>" type="number" min="0" max="99999.99" step="0.01" required></label><?php endforeach; ?></div></section><section class="o-card"><h2>Meal holidays & payment</h2><label class="o-field">Closed meal dates<textarea name="closed_dates" placeholder="YYYY-MM-DD, one per line"><?= e(implode("\n",$settings['closed_dates']??[])) ?></textarea></label><label class="o-field">Manual payment instructions<textarea name="payment_instructions" maxlength="1000"><?= e($settings['payment_instructions']??'') ?></textarea></label></section><button class="o-btn o-btn-primary">Save checkout settings</button></form><script src="/assets/workflow.js" defer></script>
